mapper.select:
SELECT
WHERE IFNULL(m.deleted, 0) = 0 AND m.quit_at IS NULL AND IFNULL(c.deleted, 0) = 0
AND c.conv_type = #{convType}
AND ( c.name LIKE CONCAT('%', #{keyword}, '%') OR pu.real_name LIKE CONCAT('%', #{keyword}, '%') OR pu.username LIKE CONCAT('%', #{keyword}, '%') )
AND m.unread_count > 0
ORDER BY m.pinned DESC, c.last_message_at DESC, c.id DESC LIMIT #{limit} OFFSET #{offset}
